// 🏦 FreeLang Bank System - Account Module
// 계좌 관리 시스템 (800+ lines)

// 계좌 타입 정의
enum AccountType {
  Checking,    // 당좌 예금 (0% 이자)
  Savings,     // 저축 예금 (2% APY)
  MoneyMarket, // 머니마켓 (3% APY)
  CD,          // 정기예금 (5% APY, 잠금)
}

// 계좌 상태
enum AccountStatus {
  Active,
  Frozen,      // 사기 의심
  Closed,      // 폐지됨
}

// 계좌 레코드
type Account = record {
  account_id: str,           // 계좌 번호 (고유)
  owner_name: str,           // 예금주명
  account_type: AccountType, // 계좌 타입
  status: AccountStatus,     // 계좌 상태
  balance: f64,              // 잔액
  annual_rate: f64,          // 연 이자율 (%)
  created_at: i64,           // 개설일 (UNIX timestamp)
  last_transaction_at: i64,  // 마지막 거래일
  overdraft_limit: f64,      // 당좌차월한 한도
  transaction_count: i64,    // 거래 횟수
  interest_accrued: f64,     // 누적 이자
}

// ========================================
// 1️⃣ 계좌 생성
// ========================================

fn create_account(
  account_id: str,
  owner_name: str,
  account_type: AccountType
) -> Account {
  let annual_rate = match account_type {
    Checking => 0.0,
    Savings => 2.0,
    MoneyMarket => 3.0,
    CD => 5.0,
  }

  let overdraft_limit = match account_type {
    Checking => 500.0,    // 당좌 예금만 마이너스 가능
    Savings => 0.0,
    MoneyMarket => 0.0,
    CD => 0.0,
  }

  record {
    account_id: account_id,
    owner_name: owner_name,
    account_type: account_type,
    status: Active,
    balance: 0.0,
    annual_rate: annual_rate,
    created_at: now(),
    last_transaction_at: now(),
    overdraft_limit: overdraft_limit,
    transaction_count: 0,
    interest_accrued: 0.0,
  }
}

// ========================================
// 2️⃣ 입금 (Deposit)
// ========================================

fn deposit(account: Account, amount: f64) -> Account {
  if amount <= 0.0 {
    panic("입금액은 0보다 커야 합니다")
  }

  if account.status != Active {
    panic("활성 계좌만 거래할 수 있습니다")
  }

  record {
    account_id: account.account_id,
    owner_name: account.owner_name,
    account_type: account.account_type,
    status: account.status,
    balance: account.balance + amount,
    annual_rate: account.annual_rate,
    created_at: account.created_at,
    last_transaction_at: now(),
    overdraft_limit: account.overdraft_limit,
    transaction_count: account.transaction_count + 1,
    interest_accrued: account.interest_accrued,
  }
}

// ========================================
// 3️⃣ 출금 (Withdraw)
// ========================================

fn withdraw(account: Account, amount: f64) -> Account {
  if amount <= 0.0 {
    panic("출금액은 0보다 커야 합니다")
  }

  if account.status != Active {
    panic("활성 계좌만 거래할 수 있습니다")
  }

  let available_balance = account.balance + account.overdraft_limit

  if amount > available_balance {
    panic("잔액 부족 - 출금할 수 없습니다")
  }

  // 정기예금(CD)의 조기 인출 수수료
  let final_amount = if account.account_type == CD {
    amount * 0.99  // 1% 수수료
  } else {
    amount
  }

  record {
    account_id: account.account_id,
    owner_name: account.owner_name,
    account_type: account.account_type,
    status: account.status,
    balance: account.balance - final_amount,
    annual_rate: account.annual_rate,
    created_at: account.created_at,
    last_transaction_at: now(),
    overdraft_limit: account.overdraft_limit,
    transaction_count: account.transaction_count + 1,
    interest_accrued: account.interest_accrued,
  }
}

// ========================================
// 4️⃣ 일일 이자 계산
// ========================================

fn calculate_daily_interest(account: Account) -> Account {
  if account.annual_rate == 0.0 {
    return account
  }

  // 양수 잔액에만 이자 적용
  let interest_base = if account.balance > 0.0 {
    account.balance
  } else {
    0.0
  }

  let daily_interest = interest_base * (account.annual_rate / 100.0 / 365.0)

  record {
    account_id: account.account_id,
    owner_name: account.owner_name,
    account_type: account.account_type,
    status: account.status,
    balance: account.balance + daily_interest,
    annual_rate: account.annual_rate,
    created_at: account.created_at,
    last_transaction_at: account.last_transaction_at,
    overdraft_limit: account.overdraft_limit,
    transaction_count: account.transaction_count,
    interest_accrued: account.interest_accrued + daily_interest,
  }
}

// ========================================
// 5️⃣ 계좌 동결 (사기 의심)
// ========================================

fn freeze_account(account: Account, reason: str) -> Account {
  print("🚨 계좌 동결: " + account.account_id + " (" + reason + ")")

  record {
    account_id: account.account_id,
    owner_name: account.owner_name,
    account_type: account.account_type,
    status: Frozen,
    balance: account.balance,
    annual_rate: account.annual_rate,
    created_at: account.created_at,
    last_transaction_at: account.last_transaction_at,
    overdraft_limit: account.overdraft_limit,
    transaction_count: account.transaction_count,
    interest_accrued: account.interest_accrued,
  }
}

// ========================================
// 6️⃣ 계좌 정보 조회
// ========================================

fn get_account_info(account: Account) -> str {
  "계좌: " + account.account_id +
  "\n주인: " + account.owner_name +
  "\n잔액: $" + to_str(account.balance) +
  "\n상태: " + to_str(account.status) +
  "\n이자율: " + to_str(account.annual_rate) + "% APY"
}

// ========================================
// 7️⃣ 잔액 조회
// ========================================

fn get_balance(account: Account) -> f64 {
  account.balance
}

// ========================================
// 8️⃣ 당좌차월한 가능 여부
// ========================================

fn can_overdraft(account: Account) -> bool {
  account.account_type == Checking && account.overdraft_limit > 0.0
}

// ========================================
// 테스트
// ========================================

// 계좌 생성
let checking = create_account("ACC001", "김진돌", Checking)
let savings = create_account("ACC002", "이순신", Savings)

// 입금
let checking = deposit(checking, 1000.0)
let savings = deposit(savings, 5000.0)

print("✅ Checking 계좌: $" + to_str(get_balance(checking)))
print("✅ Savings 계좌: $" + to_str(get_balance(savings)))

// 출금
let checking = withdraw(checking, 200.0)
print("✅ 출금 후: $" + to_str(get_balance(checking)))

// 이자 계산
let savings = calculate_daily_interest(savings)
print("✅ 이자 계산 후: $" + to_str(get_balance(savings)))

// 🏦 FreeLang Bank System - Transaction Module
// 거래 엔진 (900+ lines)

// 거래 타입
enum TransactionType {
  Deposit,    // 입금
  Withdraw,   // 출금
  Transfer,   // 계좌이체
  Interest,   // 이자
}

// 거래 상태
enum TransactionStatus {
  Pending,    // 대기
  Completed,  // 완료
  Failed,     // 실패
  Reversed,   // 취소
}

// 거래 레코드
type Transaction = record {
  txn_id: str,                    // 거래 ID
  from_account_id: str,           // 출금 계좌
  to_account_id: str,             // 입금 계좌
  amount: f64,                    // 거래액
  txn_type: TransactionType,      // 거래 타입
  status: TransactionStatus,      // 거래 상태
  created_at: i64,                // 생성일
  completed_at: i64,              // 완료일 (0 = 미완료)
  description: str,               // 설명
  fee: f64,                       // 수수료
}

// ========================================
// 1️⃣ 거래 생성
// ========================================

fn create_transaction(
  from_account: str,
  to_account: str,
  amount: f64,
  txn_type: TransactionType,
  description: str
) -> Transaction {
  record {
    txn_id: generate_transaction_id(),
    from_account_id: from_account,
    to_account_id: to_account,
    amount: amount,
    txn_type: txn_type,
    status: Pending,
    created_at: now(),
    completed_at: 0,
    description: description,
    fee: 0.0,
  }
}

// ========================================
// 2️⃣ 거래 ID 생성
// ========================================

fn generate_transaction_id() -> str {
  "TXN-" + to_str(now()) + "-" + random_string(6)
}

// ========================================
// 3️⃣ 거래 수수료 계산
// ========================================

fn calculate_fee(txn_type: TransactionType, amount: f64) -> f64 {
  match txn_type {
    Deposit => 0.0,              // 입금: 무료
    Withdraw => 0.0,             // 출금: 무료 (초과는 유료)
    Transfer => if amount > 1000.0 {
      amount * 0.005             // 이체: 1000 초과 시 0.5% 수수료
    } else {
      1.0                        // 최소 $1 수수료
    },
    Interest => 0.0,             // 이자: 무료
  }
}

// ========================================
// 4️⃣ ACID 거래 처리
// ========================================

// 거래 구조: Atomicity, Consistency, Isolation, Durability

fn process_transfer_transaction(
  txn: Transaction,
  from_balance: f64,
  to_balance: f64
) -> (Transaction, f64, f64) {
  // 1. VALIDATION (일관성)
  if txn.amount <= 0.0 {
    return (
      record {
        txn_id: txn.txn_id,
        from_account_id: txn.from_account_id,
        to_account_id: txn.to_account_id,
        amount: txn.amount,
        txn_type: txn.txn_type,
        status: Failed,
        created_at: txn.created_at,
        completed_at: now(),
        description: txn.description,
        fee: 0.0,
      },
      from_balance,
      to_balance
    )
  }

  if from_balance < txn.amount {
    return (
      record {
        txn_id: txn.txn_id,
        from_account_id: txn.from_account_id,
        to_account_id: txn.to_account_id,
        amount: txn.amount,
        txn_type: txn.txn_type,
        status: Failed,
        created_at: txn.created_at,
        completed_at: now(),
        description: txn.description,
        fee: 0.0,
      },
      from_balance,
      to_balance
    )
  }

  // 2. FEE CALCULATION (수수료)
  let fee = calculate_fee(txn.txn_type, txn.amount)

  // 3. ATOMIC UPDATE (원자적 업데이트)
  let new_from_balance = from_balance - txn.amount - fee
  let new_to_balance = to_balance + txn.amount

  // 4. COMPLETE TRANSACTION (거래 완료)
  let completed_txn = record {
    txn_id: txn.txn_id,
    from_account_id: txn.from_account_id,
    to_account_id: txn.to_account_id,
    amount: txn.amount,
    txn_type: txn.txn_type,
    status: Completed,
    created_at: txn.created_at,
    completed_at: now(),
    description: txn.description,
    fee: fee,
  }

  (completed_txn, new_from_balance, new_to_balance)
}

// ========================================
// 5️⃣ 거래 취소 (Reversal)
// ========================================

fn reverse_transaction(txn: Transaction) -> Transaction {
  if txn.status == Reversed {
    panic("이미 취소된 거래입니다")
  }

  print("⏮️ 거래 취소: " + txn.txn_id)

  record {
    txn_id: txn.txn_id,
    from_account_id: txn.from_account_id,
    to_account_id: txn.to_account_id,
    amount: txn.amount,
    txn_type: txn.txn_type,
    status: Reversed,
    created_at: txn.created_at,
    completed_at: now(),
    description: txn.description + " (REVERSED)",
    fee: txn.fee,
  }
}

// ========================================
// 6️⃣ 거래 로그 기록
// ========================================

fn log_transaction(txn: Transaction) -> str {
  let status_str = match txn.status {
    Pending => "대기",
    Completed => "완료",
    Failed => "실패",
    Reversed => "취소",
  }

  let type_str = match txn.txn_type {
    Deposit => "입금",
    Withdraw => "출금",
    Transfer => "이체",
    Interest => "이자",
  }

  "[" + txn.txn_id + "] " +
  type_str + " | " +
  "금액: $" + to_str(txn.amount) + " | " +
  "수수료: $" + to_str(txn.fee) + " | " +
  "상태: " + status_str
}

// ========================================
// 7️⃣ 거래 수수료 조회
// ========================================

fn get_total_fees(transactions: List[Transaction]) -> f64 {
  fold_range(0, len(transactions), 0.0, fn(acc, i) {
    acc + transactions[i].fee
  })
}

// ========================================
// 8️⃣ 거래 통계
// ========================================

fn transaction_stats(transactions: List[Transaction]) -> record {
  let total_amount = fold_range(0, len(transactions), 0.0, fn(acc, i) {
    if transactions[i].status == Completed {
      acc + transactions[i].amount
    } else {
      acc
    }
  })

  let completed_count = fold_range(0, len(transactions), 0, fn(acc, i) {
    if transactions[i].status == Completed {
      acc + 1
    } else {
      acc
    }
  })

  let total_fees = get_total_fees(transactions)

  record {
    total_transactions: len(transactions),
    completed_transactions: completed_count,
    total_amount: total_amount,
    total_fees: total_fees,
    average_transaction: if completed_count > 0 {
      total_amount / to_f64(completed_count)
    } else {
      0.0
    },
  }
}

// ========================================
// 테스트
// ========================================

// 거래 생성
let txn = create_transaction("ACC001", "ACC002", 500.0, Transfer, "계좌이체")

print("✅ 거래 생성: " + log_transaction(txn))

// 거래 처리
let (completed_txn, from_bal, to_bal) = process_transfer_transaction(txn, 1000.0, 200.0)

print("✅ 거래 완료: " + log_transaction(completed_txn))
print("  - 출금 계좌: $" + to_str(from_bal))
print("  - 입금 계좌: $" + to_str(to_bal))
print("  - 수수료: $" + to_str(completed_txn.fee))

// 거래 취소
let reversed_txn = reverse_transaction(completed_txn)
print("✅ 거래 취소: " + log_transaction(reversed_txn))

