			Currency:        acc.Currency,
			Balance:         acc.Balance,
			Status:          acc.Status,
			AnnualRate:      acc.AnnualRate,
			TransactionCount: acc.TransactionCount,
			InterestAccrued: acc.InterestAccrued,
		})
	}

